let lang=localStorage.getItem('course-lang')||'zh';
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
function setLang(next){lang=next;localStorage.setItem('course-lang',lang);document.documentElement.lang=lang==='zh'?'zh-CN':'en';$$('[data-lang]').forEach(b=>b.classList.toggle('active',b.dataset.lang===lang));$$('[data-i18n]').forEach(el=>{const k=el.dataset.i18n;if(lang==='en'&&copy.en[k])el.textContent=copy.en[k];else if(el.dataset.zh)el.textContent=el.dataset.zh});}
$$('[data-i18n]').forEach(el=>el.dataset.zh=el.textContent);$$('[data-lang]').forEach(b=>b.onclick=()=>setLang(b.dataset.lang));
function showTab(name){$$('[data-tab]').forEach(b=>b.classList.toggle('active',b.dataset.tab===name));['explain','code','demo'].forEach(x=>$(`#${x}Panel`).classList.toggle('hidden',x!==name));}
$$('[data-tab]').forEach(b=>b.onclick=()=>showTab(b.dataset.tab));$('#runDemo').onclick=()=>showTab('demo');
$('#copyCode').onclick=async()=>{const text=$('.codebox code').textContent;await navigator.clipboard.writeText(text);$('#copyCode').textContent=lang==='zh'?'已复制':'Copied'};
const range=$('#widthRange'),browser=$('#browser'),state=$('#layoutState'),live=$('#liveCode');let mode='fluid';
function updateLab(){const w=+range.value;$('#widthValue').textContent=w+' px';browser.style.width=(mode==='fixed'?920:w)+'px';const compact=w<720&&mode==='fluid';const grid=$('.campus .main-layout');grid.style.gridTemplateColumns=compact?'1fr':'minmax(0,1fr) 180px';$('.cards').style.gridTemplateColumns=w<520&&mode==='fluid'?'1fr':w<820&&mode==='fluid'?'repeat(2,1fr)':'repeat(3,1fr)';state.textContent=compact?'Single Column':'Main + Sidebar';live.textContent=compact?'@media (max-width: 45rem) { grid-template-columns: 1fr; }':'grid-template-columns: minmax(0, 1fr) 18rem;'}
range.oninput=updateLab;$$('[data-mode]').forEach(b=>b.onclick=()=>{mode=b.dataset.mode;$$('[data-mode]').forEach(x=>x.classList.toggle('active',x===b));updateLab()});$('#xray').onclick=e=>{browser.classList.toggle('xray');e.currentTarget.setAttribute('aria-pressed',browser.classList.contains('xray'))};
const tocLinks=$$('#tocNav a');tocLinks.forEach(a=>a.onclick=()=>{tocLinks.forEach(x=>x.classList.remove('active'));a.classList.add('active')});
const observer=new IntersectionObserver(entries=>{const hit=entries.filter(x=>x.isIntersecting).sort((a,b)=>b.intersectionRatio-a.intersectionRatio)[0];if(!hit)return;tocLinks.forEach(a=>a.classList.toggle('active',a.getAttribute('href')==='#'+hit.target.id))},{rootMargin:'-20% 0px -60% 0px',threshold:[0,.2,.5]});$$('.lesson').forEach(s=>observer.observe(s));setLang(lang);updateLab();
